public class VerifyPigLatin {
    public static void main(String[] args) {
        PigLatinTranslator translator = new PigLatinTranslator();
        String[][] cases = {
            {"apple", "appleay"},
            {"ear", "earay"},
            {"igloo", "iglooay"},
            {"object", "objectay"},
            {"under", "underay"},
            {"equal", "equalay"},
            {"pig", "igpay"},
            {"koala", "oalakay"},
            {"xenon", "enonxay"},
            {"qat", "atqay"},
            {"chair", "airchay"},
            {"queen", "eenquay"},
            {"square", "aresquay"},
            {"therapy", "erapythay"},
            {"thrush", "ushthray"},
            {"school", "oolschay"},
            {"yttria", "yttriaay"},
            {"xray", "xrayay"},
            {"yellow", "ellowyay"},
            {"rhythm", "ythmrhay"},
            {"my", "ymay"},
            {"quick fast run", "ickquay astfay unray"}
        };
        int failures = 0;
        for (String[] c : cases) {
            String actual = translator.translate(c[0]);
            if (!actual.equals(c[1])) {
                failures++;
                System.out.println("FAIL: " + c[0] + " -> " + actual + " (expected " + c[1] + ")");
            }
        }
        if (failures > 0) {
            throw new AssertionError(failures + " case(s) failed");
        }
        System.out.println("All " + cases.length + " checks passed");
    }
}
